package com.mybank.pbac.controller; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(Exception.class) ResponseEntity<?> handle(Exception e){HttpStatus s=e instanceof NoSuchElementException?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}}
